// Electron test for issue #75: the media proxy rewrites a manifest and
// Chromium's NATIVE player plays the rewritten result.
//
// What is asserted (each one is a property of the product, not of the code):
//   1. 清单整份取回：上游收到清单请求时没有 Range（半份清单改写不了）
//   2. 分片保留 Range：上游收到分片请求时带着 Range，206 与 Content-Range 回去
//   3. 广告被去掉：上游从未收到广告段的请求
//   4. 地址是绝对地址：清单里的每个地址都指向应用自己的代理
//   5. CORS 头在：跨源播放要靠它
//   6. 真 Electron 测试：改写后的清单交给浏览器原生播放器能起播（能读到时长）
//
// The media is generated by the test itself (colour bars through Chromium's own
// VideoEncoder), so the test carries no third-party content and needs no network.
//
// Run with: npm run test:media

const fs = require("fs");
const http = require("http");
const path = require("path");
const { app, session, BrowserWindow } = require("electron");
const { createMediaProxy, registerMediaScheme, SCHEME, SCOPE_SITE, SCOPE_APP } = require("../media-proxy");

const FIXTURES = path.join(__dirname, "fixtures", "media");
const TIMEOUT_MS = 60000;

/** 真实站点的广告插在内容中间：DISCONTINUITY + KEY:NONE 夹住的一段分片。 */
const AD_SEGMENT = "/ads/ad-0.ts";

// 应用自己的 scheme：必须在 app ready 之前登记。
registerMediaScheme();

async function main() {
  await app.whenReady();
  app.on("window-all-closed", () => {});

  const seg0 = fs.readFileSync(path.join(FIXTURES, "segment-0.ts"));
  const seg1 = fs.readFileSync(path.join(FIXTURES, "segment-1.ts"));

  /** 上游收到的每个请求：用来断言 Range 的去留与广告段的缺席。 */
  const upstreamRequests = [];
  let origin = "";

  const server = http.createServer((req, res) => {
    upstreamRequests.push({ path: req.url, range: req.headers.range || null });
    if (req.url === "/player.html") {
      res.writeHead(200, { "Content-Type": "text/html" });
      res.end("<body></body>");
      return;
    }
    if (req.url === "/media/index.m3u8") {
      res.writeHead(200, { "Content-Type": "application/vnd.apple.mpegurl" });
      res.end(
        [
          "#EXTM3U",
          "#EXT-X-VERSION:3",
          "#EXT-X-TARGETDURATION:1",
          "#EXT-X-MEDIA-SEQUENCE:0",
          "#EXT-X-PLAYLIST-TYPE:VOD",
          "#EXTINF:1.00000,",
          `${origin}/media/segment-0.ts`,
          "#EXT-X-DISCONTINUITY",
          "#EXT-X-KEY:METHOD=NONE",
          "#EXTINF:3.00000,",
          AD_SEGMENT,
          "#EXT-X-DISCONTINUITY",
          "#EXTINF:1.00000,",
          `${origin}/media/segment-1.ts`,
          "#EXT-X-ENDLIST",
          "",
        ].join("\n"),
      );
      return;
    }
    const body = req.url === "/media/segment-1.ts" ? seg1 : seg0;
    const range = req.headers.range;
    if (range) {
      const m = /bytes=(\d+)-(\d*)/.exec(range);
      const start = Number(m[1]);
      const end = m[2] ? Number(m[2]) : body.length - 1;
      const slice = body.subarray(start, end + 1);
      res.writeHead(206, {
        "Content-Type": "video/mp2t",
        "Content-Range": `bytes ${start}-${end}/${body.length}`,
        "Accept-Ranges": "bytes",
        "Content-Length": slice.length,
      });
      res.end(slice);
      return;
    }
    res.writeHead(200, {
      "Content-Type": "video/mp2t",
      "Accept-Ranges": "bytes",
      "Content-Length": body.length,
    });
    res.end(body);
  });
  await new Promise((r) => server.listen(0, "127.0.0.1", r));
  const port = server.address().port;
  origin = `http://127.0.0.1:${port}`;

  const s = session.fromPartition("persist:acuminata-media-test");
  createMediaProxy({
    session: s,
    getReferer: () => `${origin}/player.html`,
  });

  const win = new BrowserWindow({
    show: false,
    webPreferences: { partition: "persist:acuminata-media-test" },
  });
  await win.loadURL(`${origin}/player.html`);

  // 交给浏览器原生播放器（<video> 直接指向清单）。
  const playback = await win.webContents.executeJavaScript(`(async () => {
    const v = document.createElement("video");
    v.src = "${origin}/media/index.m3u8";
    v.muted = true;
    document.body.appendChild(v);
    const t0 = Date.now();
    while (Date.now() - t0 < 20000) {
      if (v.readyState >= 1) {
        return { duration: v.duration, readyState: v.readyState, width: v.videoWidth, error: v.error && v.error.message };
      }
      await new Promise((r) => setTimeout(r, 100));
    }
    return { duration: v.duration, readyState: v.readyState, error: v.error && v.error.message, timeout: true };
  })()`);

  // 改写后的清单：站点页拿到的就是它。
  const served = await win.webContents.executeJavaScript(`(async () => {
    const res = await fetch("${origin}/media/index.m3u8");
    return { text: await res.text(), cors: res.headers.get("access-control-allow-origin") };
  })()`);

  const failures = [];
  const expect = (cond, msg) => {
    if (!cond) failures.push(msg);
  };

  // 1. 清单整份取回：上游收到清单请求时没有 Range。
  const manifestReq = upstreamRequests.find((r) => r.path === "/media/index.m3u8");
  expect(!!manifestReq, "上游没有收到清单请求");
  expect(
    manifestReq && manifestReq.range === null,
    "清单请求带着 Range 上去了（半份清单改写不了）：" + JSON.stringify(manifestReq),
  );

  // 2. 分片保留 Range：上游收到分片请求时带着 Range。
  const segmentReqs = upstreamRequests.filter((r) => r.path.startsWith("/media/segment-"));
  expect(segmentReqs.length > 0, "上游没有收到分片请求");
  expect(
    segmentReqs.every((r) => r.range),
    "分片请求的 Range 没有保留：" + JSON.stringify(segmentReqs),
  );

  // 3. 广告被去掉：上游从未收到广告段的请求。
  expect(
    !upstreamRequests.some((r) => r.path === AD_SEGMENT),
    "广告段被请求了（广告没被去掉）",
  );
  expect(!served.text.includes(AD_SEGMENT), "改写后的清单里还有广告段");

  // 4. 地址是绝对地址，且指向应用自己的代理。
  expect(served.text.length > 0, "拿不到改写后的清单");
  const uris = served.text.split(/\r?\n/).filter((l) => l && !l.startsWith("#"));
  expect(uris.length === 2, "改写后的清单里段数不对：" + JSON.stringify(uris));
  expect(
    uris.every((u) => u.startsWith(`${SCHEME}://`)),
    "清单里有不是绝对地址的地址：" + JSON.stringify(uris),
  );
  // 站点页发起的与 Acuminata 自己发起的，在 URL 空间上分得开（ADR-0012）：
  // 「掐死站点播放器」的规则只碰 site 一侧，不误伤我们自己的播放。
  expect(
    uris.every((u) => u.startsWith(`${SCHEME}://${SCOPE_SITE}/`)),
    "站点页的清单没有指向 site 一侧：" + JSON.stringify(uris),
  );

  // 5. CORS 头在。
  expect(!!served.cors, "响应没有 CORS 头（跨源播放取不到分片）");

  // 6. 真 Electron 测试：改写后的清单交给原生播放器能起播。
  expect(!playback.error, "原生播放器起播失败：" + playback.error);
  expect(playback.duration > 0, "原生播放器读不到时长：" + JSON.stringify(playback));
  expect(playback.width > 0, "原生播放器没有解出画面：" + JSON.stringify(playback));

  server.close();

  if (failures.length) {
    console.error("MEDIA PROXY TEST FAILED");
    for (const f of failures) console.error("  ✗ " + f);
    console.error("upstream requests: " + JSON.stringify(upstreamRequests, null, 1));
    console.error("served manifest:\n" + served.text);
    return 1;
  }

  console.log(
    `MEDIA PROXY TEST PASSED: native player read duration ${playback.duration}s; ` +
      `${segmentReqs.length} segment requests kept Range; no ad segment requested`,
  );
  return 0;
}

const watchdog = setTimeout(() => {
  console.error("MEDIA PROXY TEST FAILED: timed out after " + TIMEOUT_MS + "ms");
  app.exit(1);
}, TIMEOUT_MS);

main()
  .then((code) => {
    clearTimeout(watchdog);
    app.exit(code);
  })
  .catch((err) => {
    clearTimeout(watchdog);
    console.error("MEDIA PROXY TEST FAILED: " + (err && err.stack ? err.stack : err));
    app.exit(1);
  });
